from pathlib import Path

p=Path('dashboard-transition-guard.js')
s=p.read_text(encoding='utf-8')

css_marker=".ppc-detail-grid strong{display:block;margin-top:4px;color:#315149;font-size:10px;overflow-wrap:anywhere}"
css_add=r'''
    .ppc-consult-head{margin-bottom:18px}.ppc-consult-head h1{font-size:30px;letter-spacing:-.035em}.ppc-consult-head p{max-width:650px;font-size:11px}.ppc-live-badge{display:inline-flex;align-items:center;gap:6px;margin-top:10px;padding:6px 9px;border:1px solid #d7e8e3;border-radius:999px;background:#fff;color:#56706a;font-size:8px;font-weight:850}.ppc-live-badge i{width:7px;height:7px;border-radius:50%;background:#16a67f;box-shadow:0 0 0 3px #16a67f19}
    .ppc-summary-modern{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin-bottom:14px}.ppc-stat{position:relative;overflow:hidden;min-height:82px;padding:15px 15px 14px;background:#fff;border:1px solid #dce7e4;border-radius:14px;box-shadow:0 5px 18px rgba(30,72,63,.04)}.ppc-stat-icon{position:absolute;right:13px;top:13px;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#edf8f5;color:#087866;font-size:13px;font-weight:900}.ppc-stat.warn .ppc-stat-icon{background:#fff5e7;color:#a76a19}.ppc-stat.danger .ppc-stat-icon{background:#fff0ed;color:#a84c3c}.ppc-stat small{display:block;color:#7d8d89;font-size:8px;font-weight:900;letter-spacing:.055em}.ppc-stat strong{display:block;margin-top:8px;color:#173f36;font-size:22px;line-height:1}.ppc-stat span{display:block;margin-top:6px;color:#93a09c;font-size:8px}
    .ppc-consult-panel{overflow:hidden;border-radius:15px}.ppc-filterbar{padding:14px 15px 12px;border-bottom:1px solid #edf2f0;background:#fff}.ppc-searchline{display:grid;grid-template-columns:minmax(280px,1fr) auto;gap:9px}.ppc-searchbox{display:flex;align-items:center;gap:9px;height:42px;padding:0 12px;border:1px solid #cfe0dc;border-radius:11px;background:#fbfdfc;transition:.16s}.ppc-searchbox:focus-within{border-color:#79bcae;box-shadow:0 0 0 3px #0b8f7b12;background:#fff}.ppc-searchbox span{color:#78908a;font-size:15px}.ppc-searchbox input{min-width:0;width:100%;border:0;outline:0;background:transparent;color:#244940;font:600 11px Segoe UI,Arial}.ppc-filter-chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:11px}.ppc-filter-chip{height:30px;padding:0 10px;border:1px solid #dbe7e4;border-radius:999px;background:#fff;color:#61756f;font:800 8.5px Segoe UI,Arial;cursor:pointer}.ppc-filter-chip:hover{border-color:#a8cec5;color:#087866}.ppc-filter-chip.active{border-color:#087866;background:#eaf7f3;color:#087866}.ppc-filter-chip b{margin-left:5px;font-size:8px}.ppc-clear-search{min-width:92px}
    .ppc-table-modern{min-width:940px}.ppc-table-modern th{padding:11px 14px;background:#f8fbfa}.ppc-table-modern td{padding:13px 14px}.ppc-table-modern tbody tr{transition:background .14s}.ppc-table-modern tbody tr:hover{background:#fbfdfc}.ppc-client-name-modern{min-width:225px}.ppc-avatar-modern{width:36px;height:36px;flex-basis:36px;border-radius:11px;background:linear-gradient(145deg,#e7f7f2,#f2faf8);font-size:10px}.ppc-client-name-modern strong{font-size:11px}.ppc-client-name-modern small{margin-top:4px}.ppc-contact-main{display:block;color:#36564f;font-size:9.5px;font-weight:750}.ppc-contact-sub{display:block;margin-top:4px;color:#879792;font-size:8px}.ppc-plan-main{display:block;color:#315149;font-size:9.5px;font-weight:800}.ppc-plan-sub{display:block;margin-top:4px;color:#8b9a96;font-size:8px}.ppc-connection{display:flex;align-items:center;gap:7px}.ppc-connection-dot{width:7px;height:7px;border-radius:50%;background:#aebbb7}.ppc-connection-dot.pppoe{background:#16a67f;box-shadow:0 0 0 3px #16a67f14}.ppc-action-group{display:flex;align-items:center;gap:6px;white-space:nowrap}.ppc-action{height:31px;padding:0 9px;border:1px solid #d5e3df;border-radius:8px;background:#fff;color:#49635d;font:800 8.5px Segoe UI,Arial;cursor:pointer}.ppc-action:hover{border-color:#9dc9bf;color:#087866}.ppc-action.primary{border-color:#c8e4dd;background:#edf8f5;color:#087866}.ppc-result-info-modern{display:flex;justify-content:space-between;gap:10px;padding:11px 15px;font-size:8.5px}.ppc-result-info-modern strong{color:#49635d}
    .ppc-detail-modern{width:min(820px,calc(100vw - 28px));border-radius:17px}.ppc-detail-hero{display:flex;align-items:center;gap:13px;padding:18px;border-bottom:1px solid #edf2f0;background:linear-gradient(135deg,#fbfdfc,#f2faf7)}.ppc-detail-avatar{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;border-radius:14px;background:#e4f5ef;color:#087866;font-size:14px;font-weight:950}.ppc-detail-id{min-width:0;flex:1}.ppc-detail-id h2{margin:0;color:#1d473e;font-size:17px}.ppc-detail-id p{margin:5px 0 0;color:#7d8f8a;font-size:9px}.ppc-detail-actions{display:flex;align-items:center;gap:7px}.ppc-detail-body{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:16px}.ppc-detail-section{padding:13px;border:1px solid #e5eeeb;border-radius:12px;background:#fff}.ppc-detail-section h3{margin:0 0 10px;color:#315149;font-size:10px}.ppc-detail-list{display:grid;gap:9px}.ppc-detail-item{display:grid;grid-template-columns:110px 1fr;gap:10px;align-items:start}.ppc-detail-item small{color:#8b9a96;font-size:8px}.ppc-detail-item strong{color:#35564e;font-size:9px;overflow-wrap:anywhere}.ppc-detail-section.full{grid-column:1/-1}
    .ppc-edit-layer{position:fixed;inset:0;z-index:11120;display:grid;place-items:center;padding:18px;background:#102a2570;backdrop-filter:blur(3px)}.ppc-edit-card{width:min(760px,calc(100vw - 28px));max-height:calc(100vh - 36px);overflow:auto;background:#fff;border:1px solid #dce7e4;border-radius:16px;box-shadow:0 24px 70px #0c231e38}.ppc-edit-head{display:flex;justify-content:space-between;gap:12px;padding:17px 18px;border-bottom:1px solid #edf2f0}.ppc-edit-head h2{margin:0;color:#244940;font-size:15px}.ppc-edit-head p{margin:4px 0 0;color:#80918c;font-size:8.5px}.ppc-edit-form{padding:16px 18px 18px}.ppc-edit-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ppc-edit-grid label{display:grid;gap:5px;color:#526862;font-size:9px;font-weight:750}.ppc-edit-grid label.full{grid-column:1/-1}.ppc-edit-grid input,.ppc-edit-grid select{width:100%;height:39px;padding:0 10px;border:1px solid #d2e0dd;border-radius:9px;background:#fff;color:#294b44;box-sizing:border-box;font:500 11px Segoe UI,Arial}.ppc-edit-note{margin-top:11px;padding:10px 11px;border-radius:9px;background:#f6faf8;color:#6e817c;font-size:8.5px;line-height:1.45}.ppc-edit-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px;padding-top:13px;border-top:1px solid #edf2f0}
    @media(max-width:980px){.ppc-summary-modern{grid-template-columns:repeat(2,minmax(0,1fr))}.ppc-detail-body{grid-template-columns:1fr}.ppc-detail-section.full{grid-column:1}.ppc-searchline{grid-template-columns:1fr auto}}@media(max-width:620px){.ppc-client-hub-layer{padding:18px 10px}.ppc-consult-head{display:block}.ppc-head-actions{margin-top:12px}.ppc-summary-modern{grid-template-columns:1fr 1fr}.ppc-searchline{grid-template-columns:1fr}.ppc-clear-search{display:none}.ppc-filter-chips{gap:5px}.ppc-detail-hero{align-items:flex-start;flex-wrap:wrap}.ppc-detail-actions{width:100%}.ppc-edit-grid{grid-template-columns:1fr}.ppc-edit-grid label.full{grid-column:1}}
'''
if css_marker not in s:
    raise SystemExit('client CSS marker not found')
s=s.replace(css_marker,css_marker+css_add,1)

start=s.index('  function openClientDetails(c){')
end=s.index('  function drawClientRows(){',start)
replacement=r'''  function clientFilterStatus(c){const s=norm(c?.status);if(s.includes('suspens'))return'suspended';if(s.includes('bloque'))return'blocked';if(s.includes('atras')||s.includes('inadimpl'))return'overdue';return'active'}
  function clientInitials(c){const parts=String(c?.name||'Cliente').trim().split(/\s+/).filter(Boolean);return ((parts[0]?.[0]||'C')+(parts.length>1?(parts[parts.length-1]?.[0]||''):'' )).toUpperCase()}
  function clientStatusLabel(c){const value=String(c?.status||'Ativo').trim();return value||'Ativo'}
  function closeClientDetails(){document.querySelector('.ppc-detail-layer')?.remove()}
  function openClientDetails(c){closeClientDetails();const d=document.createElement('div');d.className='ppc-detail-layer';d.innerHTML=`<section class="ppc-detail ppc-detail-modern"><div class="ppc-detail-hero"><span class="ppc-detail-avatar">${esc(clientInitials(c))}</span><div class="ppc-detail-id"><h2>${esc(c?.name||'Cliente')}</h2><p>${esc(c?.contract_number?`Contrato ${c.contract_number}`:'Cadastro sem número de contrato')} · ${esc(c?.document||'Documento não informado')}</p></div><span class="ppc-status ${statusKind(c?.status)}">${esc(clientStatusLabel(c))}</span><div class="ppc-detail-actions"><button type="button" class="ppc-action primary" data-detail-edit>Editar</button><button type="button" class="ppc-detail-close">×</button></div></div><div class="ppc-detail-body"><section class="ppc-detail-section"><h3>Dados do cliente</h3><div class="ppc-detail-list"><div class="ppc-detail-item"><small>CPF / CNPJ</small><strong>${esc(c?.document||'—')}</strong></div><div class="ppc-detail-item"><small>Telefone</small><strong>${esc(c?.phone||c?.whatsapp||'—')}</strong></div><div class="ppc-detail-item"><small>WhatsApp</small><strong>${esc(c?.whatsapp||c?.phone||'—')}</strong></div><div class="ppc-detail-item"><small>E-mail</small><strong>${esc(c?.email||'—')}</strong></div></div></section><section class="ppc-detail-section"><h3>Contrato e cobrança</h3><div class="ppc-detail-list"><div class="ppc-detail-item"><small>Contrato</small><strong>${esc(c?.contract_number||'—')}</strong></div><div class="ppc-detail-item"><small>Plano</small><strong>${esc(planName(c))}</strong></div><div class="ppc-detail-item"><small>Vencimento</small><strong>${c?.due_day?`Dia ${esc(c.due_day)}`:'—'}</strong></div><div class="ppc-detail-item"><small>Status</small><strong>${esc(clientStatusLabel(c))}</strong></div></div></section><section class="ppc-detail-section"><h3>Conexão</h3><div class="ppc-detail-list"><div class="ppc-detail-item"><small>Tipo</small><strong>${esc(c?.connection_type||'Sem integração')}</strong></div><div class="ppc-detail-item"><small>MikroTik</small><strong>${esc(routerName(c))}</strong></div><div class="ppc-detail-item"><small>Usuário PPPoE</small><strong>${esc(c?.pppoe_username||c?.pppoe_user||'—')}</strong></div><div class="ppc-detail-item"><small>Profile</small><strong>${esc(c?.mikrotik_profile||'—')}</strong></div><div class="ppc-detail-item"><small>IP</small><strong>${esc(c?.ip||'—')}</strong></div></div></section><section class="ppc-detail-section"><h3>Endereço</h3><div class="ppc-detail-list"><div class="ppc-detail-item"><small>Endereço</small><strong>${esc(clientAddress(c))}</strong></div><div class="ppc-detail-item"><small>CEP</small><strong>${esc(c?.cep||c?.zip_code||'—')}</strong></div><div class="ppc-detail-item"><small>Referência</small><strong>${esc(c?.address_reference||'—')}</strong></div><div class="ppc-detail-item"><small>MAC / Caller ID</small><strong>${esc(c?.mac_address||'—')}</strong></div></div></section></div></section>`;d.querySelector('.ppc-detail-close').onclick=()=>d.remove();d.querySelector('[data-detail-edit]').onclick=()=>{d.remove();openClientEdit(c)};d.addEventListener('mousedown',e=>{if(e.target===d)d.remove()});document.body.appendChild(d)}
  function openClientEdit(c){document.querySelector('.ppc-edit-layer')?.remove();const d=document.createElement('div');d.className='ppc-edit-layer';const statuses=['Ativo','Em atraso','Bloqueado','Suspenso'];if(c?.status&&!statuses.some(x=>norm(x)===norm(c.status)))statuses.push(String(c.status));const planOptions=clientData.plans.filter(p=>p?.active!==0&&p?.active!==false).map(p=>`<option value="${Number(p.id)||0}">${esc(p.name||'Plano')}${p.speed?` · ${esc(p.speed)}`:''}</option>`).join('');d.innerHTML=`<section class="ppc-edit-card"><div class="ppc-edit-head"><div><h2>Editar cliente</h2><p>${esc(c?.contract_number?`Contrato ${c.contract_number}`:'Atualização cadastral')} · os dados de PPPoE/MikroTik não serão alterados nesta edição.</p></div><button type="button" class="ppc-detail-close">×</button></div><form class="ppc-edit-form"><div class="ppc-edit-grid"><label class="full">Nome / Razão social<input name="name" required value="${esc(c?.name||'')}"></label><label>Nome fantasia<input name="trade_name" value="${esc(c?.trade_name||'')}"></label><label>CPF / CNPJ<input name="document" value="${esc(c?.document||'')}"></label><label>Telefone<input name="phone" value="${esc(c?.phone||'')}"></label><label>WhatsApp<input name="whatsapp" value="${esc(c?.whatsapp||'')}"></label><label class="full">E-mail<input name="email" type="email" value="${esc(c?.email||'')}"></label><label>Plano<select name="plan_id"><option value="">Sem plano</option>${planOptions}</select></label><label>Dia do vencimento<input name="due_day" type="number" min="1" max="31" value="${esc(c?.due_day||'10')}"></label><label>Status<select name="status">${statuses.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><div class="ppc-edit-note">Esta edição rápida altera apenas cadastro, plano, vencimento e status. Usuário PPPoE, senha, profile, IP e MikroTik continuam exatamente como estão.</div><div class="ppc-edit-actions"><button type="button" class="ppc-button" data-edit-cancel>Cancelar</button><button type="submit" class="ppc-button primary">Salvar alterações</button></div></form></section>`;const form=d.querySelector('form');form.elements.plan_id.value=String(Number(c?.plan_id)||'');form.elements.status.value=statuses.find(x=>norm(x)===norm(c?.status))||'Ativo';d.querySelector('.ppc-detail-close').onclick=()=>d.remove();d.querySelector('[data-edit-cancel]').onclick=()=>d.remove();d.addEventListener('mousedown',e=>{if(e.target===d)d.remove()});form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Salvando...';try{const fd=new FormData(form),planId=Number(fd.get('plan_id'))||null,plan=clientData.plans.find(p=>Number(p?.id)===planId),saved=await api().clients.save({...c,name:String(fd.get('name')||'').trim(),trade_name:String(fd.get('trade_name')||'').trim(),document:String(fd.get('document')||'').trim(),phone:String(fd.get('phone')||'').trim(),whatsapp:String(fd.get('whatsapp')||'').trim(),email:String(fd.get('email')||'').trim(),plan_id:planId,plan:plan?.name||'',plan_name:plan?.name||'',due_day:Number(fd.get('due_day'))||10,status:String(fd.get('status')||'Ativo')});d.remove();await renderClientConsult(`Cliente ${saved?.name||c?.name||''} atualizado com sucesso.`)}catch(err){submit.disabled=false;submit.textContent='Salvar alterações';alert(err?.message||String(err))}};document.body.appendChild(d)}
'''
s=s[:start]+replacement+s[end:]

start=s.index('  function drawClientRows(){')
end=s.index('  async function renderClientConsult(',start)
replacement=r'''  function drawClientRows(){if(!clientLayer)return;const input=clientLayer.querySelector('#ppc-search'),tbody=clientLayer.querySelector('#ppc-client-rows'),info=clientLayer.querySelector('#ppc-result-info'),filter=String(clientLayer.dataset.clientFilter||'all');if(!tbody)return;const q=norm(input?.value);let rows=clientData.clients.filter(c=>{if(filter!=='all'&&clientFilterStatus(c)!==filter)return false;if(!q)return true;return norm([c?.name,c?.trade_name,c?.document,c?.contract_number,c?.phone,c?.whatsapp,c?.email,c?.pppoe_username,c?.pppoe_user,c?.plan_name,c?.plan].join(' ')).includes(q)}).sort((a,b)=>String(a?.name||'').localeCompare(String(b?.name||''),'pt-BR'));const total=rows.length,shown=rows.slice(0,300);tbody.innerHTML=shown.length?shown.map(c=>`<tr><td><div class="ppc-client-name ppc-client-name-modern"><span class="ppc-avatar ppc-avatar-modern">${esc(clientInitials(c))}</span><div><strong>${esc(c?.name||'Cliente')}</strong><small>${esc(c?.contract_number?`Contrato ${c.contract_number}`:'Sem contrato')} · ${esc(c?.document||'Documento não informado')}</small></div></div></td><td><span class="ppc-contact-main">${esc(c?.phone||c?.whatsapp||'Sem telefone')}</span><span class="ppc-contact-sub">${esc(c?.email||'E-mail não informado')}</span></td><td><span class="ppc-plan-main">${esc(planName(c))}</span><span class="ppc-plan-sub">${c?.due_day?`Vence dia ${esc(c.due_day)}`:'Sem vencimento'}</span></td><td><div class="ppc-connection"><i class="ppc-connection-dot ${norm(c?.connection_type)==='pppoe'?'pppoe':''}"></i><div><span class="ppc-contact-main">${esc(c?.connection_type||'Sem integração')}</span><span class="ppc-contact-sub">${esc(c?.pppoe_username||c?.pppoe_user||routerName(c)||'')}</span></div></div></td><td><span class="ppc-status ${statusKind(c?.status)}">${esc(clientStatusLabel(c))}</span></td><td><div class="ppc-action-group"><button type="button" class="ppc-action primary" data-client-detail="${Number(c?.id)||0}">Visualizar</button><button type="button" class="ppc-action" data-client-edit="${Number(c?.id)||0}">Editar</button></div></td></tr>`).join(''):'<tr><td colspan="6"><div class="ppc-empty"><strong>Nenhum cliente encontrado</strong><br>Altere a busca ou selecione outro filtro.</div></td></tr>';if(info)info.innerHTML=total>300?`<span>Exibindo <strong>300</strong> de <strong>${integer(total)}</strong> resultados.</span><span>Refine a busca para localizar o cliente.</span>`:`<span><strong>${integer(total)}</strong> cliente${total===1?'':'s'} encontrado${total===1?'':'s'}.</span><span>Base sincronizada com o cadastro atual.</span>`;tbody.querySelectorAll('[data-client-detail]').forEach(b=>b.onclick=()=>{const c=clientData.clients.find(x=>Number(x?.id)===Number(b.dataset.clientDetail));if(c)openClientDetails(c)});tbody.querySelectorAll('[data-client-edit]').forEach(b=>b.onclick=()=>{const c=clientData.clients.find(x=>Number(x?.id)===Number(b.dataset.clientEdit));if(c)openClientEdit(c)})}
'''
s=s[:start]+replacement+s[end:]

start=s.index('  async function renderClientConsult(')
end=s.index('  async function loadProfiles(',start)
replacement=r'''  async function renderClientConsult(message='',isError=false){const h=openClientHost();if(!h)return;h.innerHTML='<div class="ppc-loading"><span></span><strong>Carregando clientes...</strong></div>';try{await loadClientData();const counts={all:clientData.clients.length,active:0,overdue:0,blocked:0,suspended:0};for(const c of clientData.clients){const k=clientFilterStatus(c);counts[k]=(counts[k]||0)+1}h.dataset.clientFilter='all';h.innerHTML=`<div class="ppc-head ppc-consult-head"><div><span class="ppc-eyebrow">GESTÃO DE ASSINANTES</span><h1>Clientes</h1><p>Consulte rapidamente cadastro, contato, plano, vencimento e conexão dos assinantes em uma única tela.</p><span class="ppc-live-badge"><i></i>Base de clientes sincronizada</span></div><div class="ppc-head-actions"><button type="button" class="ppc-button" id="ppc-refresh">↻ Atualizar</button><button type="button" class="ppc-button primary" id="ppc-go-create">＋ Cadastrar cliente</button></div></div>${message?`<div class="ppc-message ${isError?'error':''}">${esc(message)}</div>`:''}<div class="ppc-summary-modern"><article class="ppc-stat"><span class="ppc-stat-icon">◉</span><small>TOTAL DE CLIENTES</small><strong>${integer(counts.all)}</strong><span>Cadastros disponíveis</span></article><article class="ppc-stat"><span class="ppc-stat-icon">✓</span><small>ATIVOS</small><strong>${integer(counts.active)}</strong><span>Operação normal</span></article><article class="ppc-stat warn"><span class="ppc-stat-icon">!</span><small>INADIMPLENTES</small><strong>${integer(counts.overdue)}</strong><span>Em atraso</span></article><article class="ppc-stat danger"><span class="ppc-stat-icon">×</span><small>BLOQUEADOS / SUSPENSOS</small><strong>${integer(counts.blocked+counts.suspended)}</strong><span>${integer(counts.blocked)} bloqueado${counts.blocked===1?'':'s'} · ${integer(counts.suspended)} suspenso${counts.suspended===1?'':'s'}</span></article></div><section class="ppc-panel ppc-consult-panel"><div class="ppc-filterbar"><div class="ppc-searchline"><label class="ppc-searchbox"><span>⌕</span><input id="ppc-search" autocomplete="off" placeholder="Buscar por nome, CPF/CNPJ, contrato, telefone, e-mail ou PPPoE"></label><button type="button" class="ppc-button ppc-clear-search" id="ppc-clear-search">Limpar busca</button></div><div class="ppc-filter-chips"><button type="button" class="ppc-filter-chip active" data-ppc-filter="all">Todos <b>${integer(counts.all)}</b></button><button type="button" class="ppc-filter-chip" data-ppc-filter="active">Ativos <b>${integer(counts.active)}</b></button><button type="button" class="ppc-filter-chip" data-ppc-filter="overdue">Inadimplentes <b>${integer(counts.overdue)}</b></button><button type="button" class="ppc-filter-chip" data-ppc-filter="blocked">Bloqueados <b>${integer(counts.blocked)}</b></button><button type="button" class="ppc-filter-chip" data-ppc-filter="suspended">Suspensos <b>${integer(counts.suspended)}</b></button></div></div><div class="ppc-table-wrap"><table class="ppc-table ppc-table-modern"><thead><tr><th>CLIENTE</th><th>CONTATO</th><th>PLANO / VENCIMENTO</th><th>CONEXÃO</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody id="ppc-client-rows"></tbody></table></div><div class="ppc-result-info ppc-result-info-modern" id="ppc-result-info"></div></section>`;h.querySelector('#ppc-go-create').onclick=()=>renderClientCreate();h.querySelector('#ppc-refresh').onclick=()=>renderClientConsult();h.querySelector('#ppc-clear-search').onclick=()=>{const input=h.querySelector('#ppc-search');input.value='';input.focus();drawClientRows()};h.querySelector('#ppc-search').addEventListener('input',drawClientRows);h.querySelectorAll('[data-ppc-filter]').forEach(b=>b.onclick=()=>{h.dataset.clientFilter=b.dataset.ppcFilter;h.querySelectorAll('[data-ppc-filter]').forEach(x=>x.classList.toggle('active',x===b));drawClientRows()});drawClientRows()}catch(e){h.innerHTML=`<div class="ppc-message error">${esc(e?.message||e)}</div>`}}
'''
s=s[:start]+replacement+s[end:]
p.write_text(s,encoding='utf-8')

